/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

  /* Use local restrict-qualified views of the arrays.  This tells the
     compiler that these pointers do not alias, which enables more
     aggressive vectorization and keeps accumulators in registers. */
  DATA_TYPE (*restrict A_)[n]       = (DATA_TYPE (*)[n])A;
  DATA_TYPE (*restrict B_)[n]       = (DATA_TYPE (*)[n])B;
  DATA_TYPE *restrict tmp_          = tmp;
  DATA_TYPE *restrict y_            = y;
  const DATA_TYPE *restrict x_      = x;

  /* Cache the PolyBench loop bound once; this is equal to 'n' in the
     standard configuration but may be a macro expression. */
  const int n_pb = _PB_N;

#pragma scop
  /* Parallelize across rows when OpenMP is enabled.  Each iteration in
     'i' is independent: it reads distinct tmp_[i] and y_[i] and only
     reads from shared A_, B_, and x_.  Without OpenMP, this pragma is
     ignored and the code remains sequential. */
#ifdef _OPENMP
#pragma omp parallel for schedule(static)
#endif
  for (i = 0; i < n_pb; i++)
    {
      /* Row-local accumulators kept in registers.  This is equivalent
         to the original:
             tmp[i] = 0; y[i] = 0;
             for (j) { tmp[i] += A[i][j]*x[j]; y[i] += B[i][j]*x[j]; }
         but avoids repeated loads/stores of tmp[i] and y[i].  The
         reduction order over j is unchanged (still j = 0..n_pb-1). */
      DATA_TYPE tmp_i = SCALAR_VAL(0.0);
      DATA_TYPE y_i   = SCALAR_VAL(0.0);

      /* Manually unroll the inner loop by a factor of 4 to improve
         instruction-level parallelism and reduce loop overhead.  The
         compiler can still vectorize this unrolled loop. */
      int j_unroll_limit = n_pb & ~3; /* largest multiple of 4 <= n_pb */

      for (j = 0; j < j_unroll_limit; j += 4)
	{
	  DATA_TYPE x0 = x_[j];
	  DATA_TYPE x1 = x_[j + 1];
	  DATA_TYPE x2 = x_[j + 2];
	  DATA_TYPE x3 = x_[j + 3];

	  tmp_i += A_[i][j]     * x0;
	  y_i   += B_[i][j]     * x0;

	  tmp_i += A_[i][j + 1] * x1;
	  y_i   += B_[i][j + 1] * x1;

	  tmp_i += A_[i][j + 2] * x2;
	  y_i   += B_[i][j + 2] * x2;

	  tmp_i += A_[i][j + 3] * x3;
	  y_i   += B_[i][j + 3] * x3;
	}

      /* Handle remaining elements when n_pb is not a multiple of 4. */
      for (; j < n_pb; j++)
	{
	  DATA_TYPE xj = x_[j];
	  tmp_i += A_[i][j] * xj;
	  y_i   += B_[i][j] * xj;
	}

      /* Final combination.  We write each result back to memory exactly
         once per row, minimizing memory traffic compared to the
         original which updated tmp[i] and y[i] inside the j-loop. */
      tmp_[i] = tmp_i;
      y_[i]   = alpha * tmp_i + beta * y_i;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gesummv (n, alpha, beta,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(B),
		  POLYBENCH_ARRAY(tmp),
		  POLYBENCH_ARRAY(x),
		  POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

