/*
 * Main computational kernel. The whole function will be timed,
 * including the call and return.
 *
 * Optimizations vs. the original kernel:
 *   - Keep per-row accumulators in scalar variables (registers) instead
 *     of repeatedly reading/writing tmp[i] and y[i] inside the inner loop.
 *     This reduces memory traffic and makes auto-vectorization easier.
 *
 *   - Add explicit restrict-qualified local pointers to help the compiler
 *     prove that A, B, x, tmp, and y do not alias. PolyBench allocates
 *     them separately, so this is a valid assumption.
 *
 *   - Manually unroll the inner j-loop by a small factor (4) while
 *     preserving the original left-to-right accumulation order. This
 *     increases instruction-level parallelism and gives the compiler a
 *     straightforward pattern to vectorize.
 *
 *   - Optionally tile the outer i-loop (row blocking) with a modest
 *     block size so that several rows are processed together. This
 *     keeps the working set of A/B rows and the corresponding tmp/y
 *     entries in the cache hierarchy without changing the computation.
 */
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i;

  /* Create local restrict-qualified views of the arrays.
   *
   * Function parameters declared as VLA-based arrays in C are adjusted
   * to pointers, so these assignments are valid and do not copy data.
   * The restrict qualifiers tell the compiler that these pointers do
   * not alias each other, which is true for separate PolyBench buffers.
   */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict B_)[n] = B;
  DATA_TYPE *restrict tmp_    = tmp;
  DATA_TYPE *restrict x_      = x;
  DATA_TYPE *restrict y_      = y;

  /* Tile size for the outer i-loop.
   * This is a tuning parameter; 64 works well on many x64 cores.
   * It does not affect the mathematical result.
   */
  const int I_BLOCK_SIZE = 64;

#pragma scop
  /* Block the i-loop to improve locality for large N.
   * For typical PolyBench sizes this primarily serves as
   * a structural aid and does not change semantics.
   */
  for (int ii = 0; ii < _PB_N; ii += I_BLOCK_SIZE)
    {
      int i_end = ii + I_BLOCK_SIZE;
      if (i_end > _PB_N)
        i_end = _PB_N;

      for (i = ii; i < i_end; i++)
        {
          /* Row-local accumulators kept in registers. They replace the
           * original pattern:
           *   tmp[i] = 0; y[i] = 0;
           *   for (j) {
           *     tmp[i] += A[i][j] * x[j];
           *     y[i]   += B[i][j] * x[j];
           *   }
           *   y[i] = alpha * tmp[i] + beta * y[i];
           *
           * The final values of tmp[i] and y[i] are identical:
           *   tmp[i] = sum_j A[i][j] * x[j]
           *   y[i]   = alpha * tmp[i] + beta * sum_j B[i][j] * x[j]
           */
          DATA_TYPE accA = SCALAR_VAL(0.0);
          DATA_TYPE accB = SCALAR_VAL(0.0);

          /* Pointers to the current rows of A and B. */
          DATA_TYPE *restrict Ai = A_[i];
          DATA_TYPE *restrict Bi = B_[i];

          int j = 0;
          const int nPB = _PB_N;

          /* Manually unroll the inner loop by 4.
           * We explicitly write the four contributions in increasing
           * j order, so the accumulation order matches the original
           * sequential loop (up to transformations performed by the
           * compiler for vectorization).
           */
          int j_unroll = nPB & ~3; /* largest multiple of 4 <= nPB */
          for (; j < j_unroll; j += 4)
            {
              DATA_TYPE x0 = x_[j];
              DATA_TYPE x1 = x_[j + 1];
              DATA_TYPE x2 = x_[j + 2];
              DATA_TYPE x3 = x_[j + 3];

              accA += Ai[j    ] * x0;
              accB += Bi[j    ] * x0;

              accA += Ai[j + 1] * x1;
              accB += Bi[j + 1] * x1;

              accA += Ai[j + 2] * x2;
              accB += Bi[j + 2] * x2;

              accA += Ai[j + 3] * x3;
              accB += Bi[j + 3] * x3;
            }

          /* Clean up remaining elements if N is not a multiple of 4. */
          for (; j < nPB; j++)
            {
              DATA_TYPE xj = x_[j];
              accA += Ai[j] * xj;
              accB += Bi[j] * xj;
            }

          /* Store results once per row. This preserves the original
           * observable behavior of tmp[] and y[].
           */
          tmp_[i] = accA;
          y_[i]   = alpha * accA + beta * accB;
        }
    }
#pragma endscop

}


