{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    {
      x[i] = (DATA_TYPE)( i % n) / n;
      for (j = 0; j < n; j++) {
	A[i][j] = (DATA_TYPE) ((i*j+1) % n) / n;
	B[i][j] = (DATA_TYPE) ((i*j+2) % n) / n;
      }
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i;

  /* Effective problem size (may differ from the compile-time N). */
  const int n_eff = _PB_N;

  /* Optimized kernel:
   *  - Parallelizes across rows (i) when OpenMP is enabled.
   *  - Keeps per-row accumulators in registers instead of repeatedly
   *    reading/writing tmp[i] and y[i] inside the inner loop.
   *  - Traverses A and B rows, and x, with unit-stride accesses for
   *    good cache and SIMD behavior.
   */

#pragma scop
#ifdef _OPENMP
  /* Distribute rows across threads. Each iteration uses a distinct
   * i, so there are no data races on tmp[] or y[]. A, B, and x are
   * read-only inside the kernel.
   */
#pragma omp parallel for schedule(static)
#endif
  for (i = 0; i < n_eff; i++)
    {
      /* Row-local accumulators kept in registers. These implement
       * the two dot products:
       *   accA = sum_j A[i][j] * x[j]
       *   accB = sum_j B[i][j] * x[j]
       * The original code updated tmp[i] and y[i] inside the j-loop;
       * doing the accumulation in scalars and storing once per row
       * performs the same floating-point operations in the same order
       * but greatly reduces memory traffic.
       */
      DATA_TYPE accA = SCALAR_VAL(0.0);
      DATA_TYPE accB = SCALAR_VAL(0.0);

      /* Pointers to the current rows to simplify address arithmetic
       * in the inner loop. The rows are contiguous in memory.
       * 'restrict' expresses that, for the lifetime of Ai/Bi, these
       * pointers are the only means used here to access the elements
       * of their respective rows, enabling better optimization.
       */
      DATA_TYPE *restrict Ai = A[i];
      DATA_TYPE *restrict Bi = B[i];

      /* Inner loop: fused computation of the two matrix-vector products.
       * Access patterns:
       *   - Ai[j], Bi[j] are contiguous (row-major matrices).
       *   - x[j] is contiguous (1D vector).
       * This is ideal for auto-vectorization by the compiler.
       */
      for (int j = 0; j < n_eff; j++)
	{
	  DATA_TYPE xj = x[j];
	  accA += Ai[j] * xj;
	  accB += Bi[j] * xj;
	}

      /* Store results once per row. This matches:
       *   tmp[i] = sum_j A[i][j] * x[j];
       *   y[i]   = alpha * tmp[i] + beta * sum_j B[i][j] * x[j];
       */
      tmp[i] = accA;
      y[i]   = alpha * accA + beta * accB;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gesummv (n, alpha, beta,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(B),
		  POLYBENCH_ARRAY(tmp),
		  POLYBENCH_ARRAY(x),
		  POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
