/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied (semantics-preserving):
   - Keep per-row accumulators in scalars (tmp_i, y_i) so tmp[i] and y[i]
     are written exactly once per row, instead of on every j-iteration.
   - Parallelize across tiles of the outer i-loop with OpenMP; rows are
     independent, so this is safe.
   - Tile the j-dimension to bound the working set when N is large, and
     manually unroll the innermost j-loop by 4 for better ILP.
   - All floating-point updates follow the same per-(i,j) order as the
     original implementation, preserving its reduction order.
 */
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

  /* Tunable tile sizes.
     Ti: number of rows per i-tile (and OpenMP chunk size).
     Tj: number of columns per j-tile (improves cache locality for A/B/x). */
  const int Ti = 64;
  const int Tj = 256;

#pragma scop
  /* Parallelize across i-tiles.  Each (i) iteration is independent:
     it reads distinct rows A[i][*], B[i][*], writes distinct tmp[i], y[i],
     and only reads shared input vector x[*]. */
#pragma omp parallel for schedule(static)
  for (int ii = 0; ii < _PB_N; ii += Ti)
  {
    int i_max = ii + Ti;
    if (i_max > _PB_N)
      i_max = _PB_N;

    for (i = ii; i < i_max; ++i)
    {
      /* Per-row accumulators kept in registers.
         This is equivalent to:
           tmp[i] = 0; y[i] = 0;
           for j: tmp[i] += A[i][j]*x[j]; y[i] += B[i][j]*x[j];
         but avoids repeated loads/stores of tmp[i] and y[i]. */
      DATA_TYPE tmp_i = SCALAR_VAL(0.0);
      DATA_TYPE y_i   = SCALAR_VAL(0.0);

      /* Row pointers reduce address computation overhead. */
      DATA_TYPE *Ai = A[i];
      DATA_TYPE *Bi = B[i];

      /* Tile the j dimension.  For each row, we still visit j in strictly
         increasing order 0.._PB_N-1, so the reduction order matches the
         original kernel exactly. */
      for (int jj = 0; jj < _PB_N; jj += Tj)
      {
        int j_max = jj + Tj;
        if (j_max > _PB_N)
          j_max = _PB_N;

        /* Manually unroll the innermost loop by 4.
           The operations are executed in j order:
             jj, jj+1, jj+2, jj+3, ...
           just as in the original implementation. */
        int j_end_unroll = j_max - ((j_max - jj) & 3);
        for (j = jj; j < j_end_unroll; j += 4)
        {
          DATA_TYPE x0 = x[j];
          tmp_i += Ai[j] * x0;
          y_i   += Bi[j] * x0;

          DATA_TYPE x1 = x[j + 1];
          tmp_i += Ai[j + 1] * x1;
          y_i   += Bi[j + 1] * x1;

          DATA_TYPE x2 = x[j + 2];
          tmp_i += Ai[j + 2] * x2;
          y_i   += Bi[j + 2] * x2;

          DATA_TYPE x3 = x[j + 3];
          tmp_i += Ai[j + 3] * x3;
          y_i   += Bi[j + 3] * x3;
        }

        /* Handle any remaining (at most three) elements in this tile. */
        for (; j < j_max; ++j)
        {
          DATA_TYPE xj = x[j];
          tmp_i += Ai[j] * xj;
          y_i   += Bi[j] * xj;
        }
      }

      /* Finalize results for row i.
         tmp[i] and y[i] match exactly the values computed by the
         original scalar reference kernel. */
      tmp[i] = tmp_i;
      y[i]   = alpha * tmp_i + beta * y_i;
    }
  }
#pragma endscop

}


